import{_ as e,o as r,c as n,a2 as o}from"./chunks/framework.XaTYfhfj.js";const p=JSON.parse('{"title":"Step 12: Technical Glossary & Forensic Lexicon","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),d={name:"11-glossary.md"};function s(i,t,a,c,l,g){return r(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="step-12-technical-glossary-forensic-lexicon" tabindex="-1">Step 12: Technical Glossary &amp; Forensic Lexicon <a class="header-anchor" href="#step-12-technical-glossary-forensic-lexicon" aria-label="Permalink to &quot;Step 12: Technical Glossary &amp; Forensic Lexicon&quot;">​</a></h1><p>This glossary defines the digital forensics, cyber-defense, networking, and web development terminology used across TruthGuard.</p><hr><table tabindex="0"><thead><tr><th>Term</th><th>Technical Definition &amp; Practical Meaning</th><th>Context in TruthGuard</th></tr></thead><tbody><tr><td><strong>Deepfake</strong></td><td>Synthetic media generated by deep neural networks (GANs, diffusion transformers) to impersonate human likeness or voice.</td><td>The core threat targeted by TruthLence (<code>F1</code>) and DeepGuard (<code>F3</code>).</td></tr><tr><td><strong>Diffusion Model</strong></td><td>Machine learning architecture that generates high-fidelity images by iteratively removing Gaussian noise.</td><td>Source of synthetic pixel artifacts identified in <code>truthlence</code>.</td></tr><tr><td><strong>Error Level Analysis (ELA)</strong></td><td>A forensic technique that identifies areas of an image with differing compression ratios, revealing spliced regions.</td><td>Conceptual principle behind TruthLence compression analysis.</td></tr><tr><td><strong>EXIF (Exchangeable Image File Format)</strong></td><td>Metadata standard embedded in raster images recording camera hardware, exposure settings, and timestamps.</td><td>Parsed by <code>exifr</code> in DEEP SCAN (<code>fileAnalyzer.ts</code>).</td></tr><tr><td><strong>GPS Geotagging</strong></td><td>Latitude, longitude, and altitude coordinates embedded in EXIF tags at the moment of photo capture.</td><td>Extracted and plotted on <code>GpsMap.tsx</code>.</td></tr><tr><td><strong>SHA-256 (Secure Hash Algorithm)</strong></td><td>Cryptographic hash function generating a unique 256-bit (64-character hex) fingerprint from file bytes.</td><td>Computed via Web Crypto API in <code>camara-temper</code> and <code>mediavault 2</code>.</td></tr><tr><td><strong>Vishing (Voice Phishing)</strong></td><td>Telecommunication fraud where attackers use synthetic voice cloning or social engineering to extract credentials.</td><td>Analyzed in <code>calldetection-sms-contentdetection/src/pages/CallDetection.tsx</code>.</td></tr><tr><td><strong>Smishing (SMS Phishing)</strong></td><td>Mobile text scams containing deceptive links or urgent requests for financial transfers.</td><td>Analyzed in <code>calldetection-sms-contentdetection/src/pages/SmsDetection.tsx</code>.</td></tr><tr><td><strong>Optical Flow</strong></td><td>The pattern of apparent motion of image objects between consecutive video frames.</td><td>Used to detect surveillance camera lens tampering and freeze loops.</td></tr><tr><td><strong>Micro-Frontend</strong></td><td>Architectural pattern extending microservices to the frontend, splitting web apps into independent sub-applications.</td><td>TruthGuard&#39;s federated hub connecting modules running across ports 5173–5184.</td></tr><tr><td><strong>Dynamic Port Probing</strong></td><td>Client-side network technique issuing non-blocking HEAD requests to discover active services across port ranges.</td><td>Implemented in <code>FeatureEmbed.tsx</code> (<code>checkPort</code> across ports 5176–5200).</td></tr><tr><td><strong>Zustand</strong></td><td>Minimalist reactive state management library for React based on immutable hook selectors without providers.</td><td>Powers file queues and activity logs in <code>mediavault 2/src/lib/mediavault-store.ts</code>.</td></tr><tr><td><strong>Vite</strong></td><td>Frontend build tool that serves code via native ES Modules during development and bundles with Rollup.</td><td>Powers local HMR and production builds across all subprojects.</td></tr><tr><td><strong>Supabase Edge Functions</strong></td><td>Serverless TypeScript/JavaScript compute workers running on the Deno V8 engine close to clients.</td><td>Runs <code>analyze-media</code> and <code>analyze-content</code> inference pipelines.</td></tr><tr><td><strong>Row Level Security (RLS)</strong></td><td>PostgreSQL security feature restricting database rows accessible to a given SQL query based on user identity.</td><td>Secures the <code>profiles</code> table so users can only access their own data.</td></tr><tr><td><strong>GoTrue</strong></td><td>Open-source authentication API supporting JWT issuance, password hashing, and OAuth identity providers.</td><td>The authentication engine powering Supabase Auth in <code>AuthContext.tsx</code>.</td></tr><tr><td><strong>Media Bias/Fact Check (MBFC)</strong></td><td>Independent research organization rating media outlets on factual reporting credibility and political bias.</td><td>Grounding standard used for source reliability tiers in <code>VeritAIApp.tsx</code>.</td></tr><tr><td><strong>Framer Motion</strong></td><td>Physics-based animation library for React enabling fluid gesture controls and staggered transitions.</td><td>Powers animated confidence bars, radar sweeps, and card entrance effects.</td></tr><tr><td><strong>Lucide Icons</strong></td><td>Open-source SVG icon library designed for modern clean user interfaces.</td><td>Provides cyber-defense iconography (<code>Shield</code>, <code>Cpu</code>, <code>Phone</code>, <code>Lock</code>).</td></tr><tr><td><strong>Tailwind CSS</strong></td><td>Utility-first CSS framework enabling rapid composition of design systems using atomic classes.</td><td>Implements TruthGuard&#39;s custom NVIDIA-inspired dark styling.</td></tr></tbody></table>',4)])])}const h=e(d,[["render",s]]);export{p as __pageData,h as default};
